//
// Lab report: synthetic Formula vs Round-Robin benchmark, one measure at a time.
// Roundtable 2026-09-28, Decision 18: no overall winner and no count of wins across
// measures; restrained wording per the June audit. Numbers come from
// benchmarkResults.ts, generated by scripts/benchmark.ts --json.

import { POOLED, PRESETS, RUNS_PER_PRESET, type MetricResult } from './benchmarkResults';

interface Props {
  onBack: () => void;
}

interface MetricInfo {
  label: string;
  definition: string;
  higherBetter: boolean;
  decimals: number;
}

const METRICS: Record<string, MetricInfo> = {
  redZone: { label: 'Red-zone placements', definition: 'Placements onto a team whose ratio was below 8.5 (the 5th percentile of historical ratios) just before the patient arrived.', higherBetter: false, decimals: 1 },
  minRatio: { label: 'Lowest receiving ratio', definition: 'The lowest ratio of a receiving team just before a placement. It is not the lowest ratio any team reached during the shift.', higherBetter: true, decimals: 1 },
  avgRatio: { label: 'Mean receiving ratio', definition: 'Mean ratio of the receiving team just before each placement. Very high ratios on nearly empty teams dominate it.', higherBetter: true, decimals: 1 },
  b2bHA: { label: 'Back-to-back Red or Yellow', definition: 'A Red or Yellow placed on a team that received a Red or Yellow within the previous 30 minutes.', higherBetter: false, decimals: 2 },
  slams: { label: 'Slams', definition: 'A patient placed on a team that received any patient within the previous 60 minutes.', higherBetter: false, decimals: 2 },
  countSpread: { label: 'Patient count spread', definition: 'Most minus fewest patients across the open A-side teams at the end of the shift.', higherBetter: false, decimals: 1 },
  acuitySpread: { label: 'Acuity spread', definition: 'Most minus least acuity-weighted arrivals (Red 4, Yellow 2, Purple 1) across the open A-side teams.', higherBetter: false, decimals: 1 },
  stressSpread: { label: 'Patients per unit of strength, spread', definition: 'Patients divided by team strength, most minus least across teams. Strength is the steady-state staffing, so temporary changes during the shift are not reflected.', higherBetter: false, decimals: 3 },
  acuityStressSpread: { label: 'Acuity per unit of strength, spread', definition: 'Acuity-weighted arrivals divided by steady-state team strength, most minus least across teams.', higherBetter: false, decimals: 3 },
  avgRatioSpread: { label: 'Spread of team mean ratios', definition: 'Highest minus lowest per-team mean receiving ratio. Skewed by nearly empty teams.', higherBetter: false, decimals: 1 },
};

const GROUPS: { title: string; keys: string[]; note: string }[] = [
  {
    title: 'Receiving team at the moment of placement',
    keys: ['redZone', 'minRatio', 'avgRatio'],
    note: 'The formula placed fewer patients onto teams below 8.5 and its lowest receiving ratio was higher. The mean receiving ratio was higher under round-robin; both means are dominated by very high ratios on nearly empty teams, and that difference is not statistically significant.',
  },
  {
    title: 'Placements close together on one team',
    keys: ['b2bHA', 'slams'],
    note: 'Both were slightly more frequent under the formula, by about 0.14 back-to-back Red or Yellow placements and 0.26 slams per shift. The differences are small in absolute terms but statistically significant, so the two methods are not equivalent on these measures. The formula sends each patient to the team with the most room, which can be the same team twice in a row.',
  },
  {
    title: 'Spread across teams',
    keys: ['countSpread', 'acuitySpread', 'stressSpread', 'acuityStressSpread', 'avgRatioSpread'],
    note: 'Round-robin gave more even patient counts and more even acuity-weighted arrivals. The formula gave more even workload relative to team strength. The strength-relative measures use steady-state staffing and do not track staffing changes within a shift. The spread of team mean ratios favored the formula with a very small effect size.',
  },
];

const fmt = (v: number, decimals: number) => v.toFixed(decimals);
const fmtP = (p: number) => (p < 0.001 ? 'p < 0.001' : `p = ${p < 0.01 ? p.toFixed(3) : p.toFixed(2)}`);
const n = (r: MetricResult) => r.wins + r.ties + r.losses;
const byKey = (rows: MetricResult[], key: string) => rows.find(r => r.key === key)!;

function direction(r: MetricResult, info: MetricInfo): string {
  if (r.p >= 0.05) return 'No statistically significant difference';
  const formulaHigher = r.formulaMean > r.roundRobinMean;
  const formulaBetter = info.higherBetter ? formulaHigher : !formulaHigher;
  return `${formulaBetter ? 'Formula' : 'Round-robin'} better on this measure`;
}

function MetricCard({ r }: { r: MetricResult }) {
  const info = METRICS[r.key];
  return (
    <div className="rounded-xl border border-slate-300 dark:border-white/10 bg-white/60 dark:bg-white/5 p-3 space-y-2">
      <div className="flex items-baseline justify-between gap-2 flex-wrap">
        <h3 className="font-semibold text-slate-900 dark:text-white text-sm">{info.label}</h3>
        <span className="text-[11px] text-slate-500 dark:text-slate-400">{info.higherBetter ? 'Higher is better' : 'Lower is better'}</span>
      </div>
      <p className="text-xs text-slate-500 dark:text-slate-400">{info.definition}</p>
      <div className="grid grid-cols-2 gap-2 text-center">
        <div className="rounded-lg bg-slate-100 dark:bg-white/5 py-2">
          <div className="text-[11px] text-slate-500 dark:text-slate-400">Formula</div>
          <div className="font-semibold tabular-nums text-slate-900 dark:text-white">{fmt(r.formulaMean, info.decimals)}</div>
          <div className="text-[10px] tabular-nums text-slate-500">SD {fmt(r.formulaSD, info.decimals)}</div>
        </div>
        <div className="rounded-lg bg-slate-100 dark:bg-white/5 py-2">
          <div className="text-[11px] text-slate-500 dark:text-slate-400">Round-robin</div>
          <div className="font-semibold tabular-nums text-slate-900 dark:text-white">{fmt(r.roundRobinMean, info.decimals)}</div>
          <div className="text-[10px] tabular-nums text-slate-500">SD {fmt(r.roundRobinSD, info.decimals)}</div>
        </div>
      </div>
      <p className="text-xs text-slate-600 dark:text-slate-300">
        {direction(r, info)} ({fmtP(r.p)}, effect size d = {Math.abs(r.cohensD).toFixed(2)}).
        Formula better in {r.wins.toLocaleString()} of {n(r).toLocaleString()} shifts, round-robin in {r.losses.toLocaleString()}, equal in {r.ties.toLocaleString()}.
      </p>
    </div>
  );
}

function PresetTable({ metrics }: { metrics: MetricResult[] }) {
  return (
    <table className="w-full text-[11px] tabular-nums">
      <thead>
        <tr className="text-slate-500 dark:text-slate-400">
          <th className="text-left font-medium py-1">Measure</th>
          <th className="text-right font-medium">Formula</th>
          <th className="text-right font-medium">Round-robin</th>
          <th className="text-right font-medium">p</th>
        </tr>
      </thead>
      <tbody className="text-slate-700 dark:text-slate-200">
        {metrics.map(r => {
          const info = METRICS[r.key];
          return (
            <tr key={r.key} className="border-t border-slate-200 dark:border-white/10">
              <td className="text-left py-1 pr-2">{info.label}</td>
              <td className="text-right">{fmt(r.formulaMean, info.decimals)}</td>
              <td className="text-right">{fmt(r.roundRobinMean, info.decimals)}</td>
              <td className="text-right pl-2 whitespace-nowrap">{r.p < 0.001 ? '< 0.001' : r.p.toFixed(r.p < 0.01 ? 3 : 2)}</td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );
}

export default function BenchmarkReport({ onBack }: Props) {
  const total = RUNS_PER_PRESET * PRESETS.length;
  return (
    <div className="dashboard-bg min-h-screen overflow-y-auto px-4 py-6">
      <div className="max-w-lg mx-auto space-y-5 pb-12">
        <button
          onClick={onBack}
          className="min-h-[44px] bg-slate-200 dark:bg-white/10 text-slate-600 dark:text-slate-300 rounded-xl px-4 py-2 font-semibold text-sm active:bg-slate-300 dark:active:bg-white/20 border border-slate-300 dark:border-white/10"
        >
          ← Back
        </button>

        <header className="space-y-2">
          <h1 className="text-xl font-bold text-slate-900 dark:text-white">Formula vs round-robin: synthetic benchmark</h1>
          <p className="text-sm text-slate-600 dark:text-slate-300">
            Research report, run 2026-09-28. {total.toLocaleString()} simulated 8-hour shifts: {RUNS_PER_PRESET} seeds for each of {PRESETS.length} staffing presets.
            Both methods receive the same patients at the same times in each shift. Each measure is reported on its own.
          </p>
          <div className="rounded-xl border border-slate-300 dark:border-white/10 bg-slate-100 dark:bg-white/5 p-3 text-xs text-slate-600 dark:text-slate-300 space-y-1.5">
            <p>This compares two routing rules inside a model. It does not measure patient outcomes or clinical safety.</p>
            <p>Patients and staffing presets are synthetic, but the model's parameters include the provider weights from the department's Delphi survey, so the run is not independent of NYU inputs.</p>
            <p>The measures are not combined into a score, and wins are not counted across measures: which measures are counted changes any such tally.</p>
          </div>
        </header>

        {GROUPS.map(g => (
          <section key={g.title} className="space-y-2">
            <h2 className="font-semibold text-slate-800 dark:text-slate-100">{g.title}</h2>
            <p className="text-xs text-slate-600 dark:text-slate-300">{g.note}</p>
            {g.keys.map(k => <MetricCard key={k} r={byKey(POOLED, k)} />)}
          </section>
        ))}

        <section className="space-y-2">
          <h2 className="font-semibold text-slate-800 dark:text-slate-100">By staffing preset</h2>
          <p className="text-xs text-slate-600 dark:text-slate-300">
            Means per shift, {RUNS_PER_PRESET} shifts each. Results differ by preset: for example, on the two-team Night Shift preset
            round-robin gave the smaller spread of patients per unit of strength.
          </p>
          {PRESETS.map(p => (
            <details key={p.name} className="rounded-lg border border-slate-300 dark:border-white/10 overflow-hidden">
              <summary className="px-3 py-2 text-sm font-medium text-slate-700 dark:text-slate-200 cursor-pointer min-h-[40px] flex items-center bg-slate-100 dark:bg-white/5">
                {p.label}
              </summary>
              <div className="px-3 pb-3 pt-1 overflow-x-auto">
                <PresetTable metrics={p.metrics} />
              </div>
            </details>
          ))}
        </section>

        <section className="space-y-1.5 text-xs text-slate-600 dark:text-slate-300">
          <h2 className="font-semibold text-sm text-slate-800 dark:text-slate-100">Method</h2>
          <p>Script: <code>scripts/benchmark.ts</code> (seeds 1 to {RUNS_PER_PRESET}, 8-hour shifts). Model: acuity weights 4:2:1 with linear decay to zero at 180, 180 and 90 minutes; the frozen provider weights in <code>constants.ts</code>; no assignment buffers; teams ranked on their current ratio.</p>
          <p>p values are two-tailed paired t-tests on the per-shift values; d is the mean paired difference divided by its standard deviation. "Better in N shifts" compares the two methods shift by shift on that one measure.</p>
          <p>All ratios are the receiving team's ratio just before placement. Spreads cover open A-side teams; Trauma and closed teams are excluded.</p>
        </section>

        <footer className="pt-2 text-center text-[11px] text-slate-500 dark:text-slate-400">© 2026 New York University</footer>
      </div>
    </div>
  );
}
